INSERT INTO care_knowledge (title, category, content, author) VALUES
('Kitten First Week Checklist', 'Kittens', 'Schedule vet visit within 48 hours. Provide warm bedding, kitten formula if under 4 weeks, and litter box with low sides.', 'Dr. Amira Hassan'),
('Signs of Urinary Blockage', 'Health', 'Straining in litter box, crying, licking genitals, or blood in urine require emergency vet visit immediately.', 'CatConnect Team'),
('Introducing a New Cat', 'Behavior', 'Use separate room for 1-2 weeks. Swap scents via blankets. Supervised short meetings before full integration.', 'Dr. Amira Hassan'),
('Dental Care at Home', 'Grooming', 'Brush teeth 2-3 times weekly with cat toothpaste. Dental treats help but do not replace brushing.', 'CatConnect Team'),
('Senior Cat Nutrition', 'Nutrition', 'Cats 11+ need easily digestible protein, joint supplements, and more frequent vet checkups every 6 months.', 'Dr. Amira Hassan');
